<?php
namespace App\Http\Controllers\Finance;
use App\Http\Controllers\Controller; use App\Models\FinancialTransaction; use App\Models\Receivable; use App\Models\ReceivablePayment; use App\Models\CustomerPrepayment; use App\Models\Payable; use App\Models\PayablePayment; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Illuminate\Http\Request; use Illuminate\View\View; use Illuminate\Http\RedirectResponse;
class TransactionController extends Controller {
 public function index(Request $r): View { abort_unless($r->user()->canAccess('transactions'),403); $q=FinancialTransaction::with('recorder')->latest('transaction_date'); if($r->filled('type')) $q->where('type',$r->query('type')); return view('finance.transactions.index',['transactions'=>$q->paginate(30)->withQueryString(),'type'=>$r->query('type')]); }
 public function create(Request $r): View { abort_unless($r->user()->canDo('transactions','create'),403); $configured=Schema::hasTable('finance_payment_accounts')?DB::table('finance_payment_accounts')->where('is_active',true)->orderBy('name')->pluck('name')->all():[]; $farmAccounts=array_values(array_unique(array_merge($configured,['Cash on Hand','Petty Cash (UGX)','Petty Cash (USD)','Centenary Bank - Sales','Centenary Bank - Operations','Centenary Bank - Garden'],FinancialTransaction::query()->whereNotNull('account')->distinct()->orderBy('account')->pluck('account')->all()))); $paymentMethods=Schema::hasTable('finance_payment_methods')?DB::table('finance_payment_methods')->where('is_active',true)->orderBy('name')->get():collect([(object)['code'=>'cash','name'=>'Cash'],(object)['code'=>'bank','name'=>'Bank'],(object)['code'=>'mobile_money','name'=>'Mobile money'],(object)['code'=>'credit','name'=>'Credit']]); $receivables=Receivable::where('status','open')->orderBy('customer_name')->get(); $payables=Payable::where('status','open')->orderBy('supplier_name')->get(); return view('finance.transactions.create',compact('farmAccounts','paymentMethods','receivables','payables')); }
 public function store(Request $r): RedirectResponse { abort_unless($r->user()->canDo('transactions','create'),403); $data=$r->validate(['transaction_date'=>['required','date'],'type'=>['required','in:money_received,money_paid,transfer,journal'],'account'=>['required','string','max:120'],'counterparty'=>['nullable','string','max:160'],'amount'=>['required','numeric','min:0.01'],'payment_method'=>['nullable','in:cash,bank,mobile_money,credit'],'reference'=>['nullable','string','max:80'],'description'=>['required','string','max:1000'],'receipt_kind'=>['nullable','in:general,customer_payment,customer_prepayment'],'payment_kind'=>['nullable','in:general,supplier_bill'],'receivable_id'=>['nullable','exists:receivables,id'],'payable_id'=>['nullable','exists:payables,id']]); if(in_array($data['type'],['money_received','money_paid'],true) && empty($data['payment_method'])) return back()->withErrors(['payment_method'=>'Choose how the money moved.'])->withInput(); if(in_array($data['type'],['transfer','journal'],true) && empty($data['counterparty'])) return back()->withErrors(['counterparty'=>'Choose the other account.'])->withInput(); if($data['type']==='transfer' && $data['account']===$data['counterparty']) return back()->withErrors(['counterparty'=>'Choose a different account.'])->withInput(); if($data['type']==='money_received' && ($data['receipt_kind'] ?? 'general')==='customer_payment' && empty($data['receivable_id'])) return back()->withErrors(['receivable_id'=>'Choose the customer amount being paid.'])->withInput(); if($data['type']==='money_paid' && ($data['payment_kind'] ?? 'general')==='supplier_bill' && empty($data['payable_id'])) return back()->withErrors(['payable_id'=>'Choose the supplier bill being paid.'])->withInput(); $kind=$data['receipt_kind']??'general';$payKind=$data['payment_kind']??'general'; unset($data['receipt_kind'],$data['payment_kind'],$data['receivable_id'],$data['payable_id']); if(in_array($data['type'],['transfer','journal'],true)) $data['payment_method']=null; try { DB::transaction(function() use($data,$r,$kind,$payKind){ $transaction=FinancialTransaction::create($data+['recorded_by'=>$r->user()->id]); if($kind==='customer_payment'){ $due=Receivable::lockForUpdate()->findOrFail($r->receivable_id);$balance=(float)$due->amount-(float)$due->amount_paid;if((float)$data['amount']>$balance) throw new \RuntimeException('Payment is more than the customer balance.');$due->amount_paid+=(float)$data['amount'];$due->status=(float)$due->amount_paid>=(float)$due->amount?'paid':'open';$due->save();ReceivablePayment::create(['receivable_id'=>$due->id,'received_date'=>$data['transaction_date'],'amount'=>$data['amount'],'farm_account'=>$data['account'],'payment_method'=>$data['payment_method'],'reference'=>$data['reference'],'recorded_by'=>$r->user()->id]); } elseif($kind==='customer_prepayment'){ CustomerPrepayment::create(['customer_name'=>$data['counterparty'],'received_date'=>$data['transaction_date'],'amount'=>$data['amount'],'amount_used'=>0,'farm_account'=>$data['account'],'payment_method'=>$data['payment_method'],'reference'=>$data['reference'],'recorded_by'=>$r->user()->id]); } if($payKind==='supplier_bill'){ $bill=Payable::lockForUpdate()->findOrFail($r->payable_id);$balance=(float)$bill->amount-(float)$bill->amount_paid;if((float)$data['amount']>$balance) throw new \RuntimeException('Payment is more than the supplier bill.');$bill->amount_paid+=(float)$data['amount'];$bill->status=(float)$bill->amount_paid>=(float)$bill->amount?'paid':'open';$bill->save();PayablePayment::create(['payable_id'=>$bill->id,'paid_date'=>$data['transaction_date'],'amount'=>$data['amount'],'farm_account'=>$data['account'],'payment_method'=>$data['payment_method'],'reference'=>$data['reference'],'recorded_by'=>$r->user()->id]); } }); } catch(\RuntimeException $e) { return back()->withErrors(['amount'=>$e->getMessage()])->withInput(); } return redirect()->route('finance.transactions.index')->with('status','Transaction recorded.'); }
 public function generalLedger(Request $r): View { abort_unless($r->user()->canAccess('general-ledger'),403); $entries=collect(); FinancialTransaction::orderBy('transaction_date')->orderBy('id')->get()->each(function($transaction) use ($entries) { $source=$transaction->account; $other=$transaction->counterparty ?: 'Unspecified account'; if($transaction->type==='money_received') { $entries->push((object)['date'=>$transaction->transaction_date,'account'=>$source,'description'=>$transaction->description,'reference'=>$transaction->reference,'debit'=>$transaction->amount,'credit'=>0]); $entries->push((object)['date'=>$transaction->transaction_date,'account'=>'Income / '.$other,'description'=>$transaction->description,'reference'=>$transaction->reference,'debit'=>0,'credit'=>$transaction->amount]); } elseif($transaction->type==='money_paid') { $entries->push((object)['date'=>$transaction->transaction_date,'account'=>'Expense / '.$other,'description'=>$transaction->description,'reference'=>$transaction->reference,'debit'=>$transaction->amount,'credit'=>0]); $entries->push((object)['date'=>$transaction->transaction_date,'account'=>$source,'description'=>$transaction->description,'reference'=>$transaction->reference,'debit'=>0,'credit'=>$transaction->amount]); } else { $entries->push((object)['date'=>$transaction->transaction_date,'account'=>$source,'description'=>$transaction->description,'reference'=>$transaction->reference,'debit'=>$transaction->type==='journal' ? $transaction->amount : 0,'credit'=>$transaction->type==='transfer' ? $transaction->amount : 0]); $entries->push((object)['date'=>$transaction->transaction_date,'account'=>$other,'description'=>$transaction->description,'reference'=>$transaction->reference,'debit'=>$transaction->type==='transfer' ? $transaction->amount : 0,'credit'=>$transaction->type==='journal' ? $transaction->amount : 0]); } }); $accounts=$entries->pluck('account')->unique()->sort()->values(); if($r->filled('account')) $entries=$entries->where('account',$r->query('account'))->values(); $totalDebit=$entries->sum('debit'); $totalCredit=$entries->sum('credit'); return view('finance.transactions.general-ledger',compact('entries','accounts','totalDebit','totalCredit')); }
 public function cashBook(Request $r): View { abort_unless($r->user()->canAccess('cash-book'),403); $rows=FinancialTransaction::where('payment_method','cash')->orderBy('transaction_date')->orderBy('id')->get(); $balance=0; $rows->each(function($x) use (&$balance){$balance += $x->type==='money_received' ? $x->amount : -$x->amount; $x->running_balance=$balance;}); return view('finance.transactions.cash-book',compact('rows','balance')); }
 public function bankBook(Request $r): View { abort_unless($r->user()->canAccess('bank-book'),403); $accounts=collect(['Centenary Bank - Sales','Centenary Bank - Operations','Centenary Bank - Garden'])->merge(FinancialTransaction::where('payment_method','bank')->distinct()->orderBy('account')->pluck('account'))->unique()->values(); $q=FinancialTransaction::where('payment_method','bank'); if($r->filled('account')) $q->where('account',$r->query('account')); $rows=$q->orderBy('transaction_date')->orderBy('id')->get(); $balance=0; $rows->each(function($x) use (&$balance){$balance += $x->type==='money_received' ? $x->amount : -$x->amount; $x->running_balance=$balance;}); return view('finance.transactions.bank-book',compact('rows','balance','accounts')); }
}
